stimulus.text:
SELECT ENAME
FROM EMP
WHERE JOB = 'CLERK' OR ENAME LIKE 'K%' AND SAL >= 3000;

SELECT COUNT(*)
FROM T1 CROSS JOIN T2
WHERE T1.C1 <> T2.C1;

SELECT 주문번호, 상품코드, 최고금액
FROM 주문
ORDER BY ㉠;

SELECT A.ID
  FROM A
 WHERE A.ID NOT IN (SELECT B.ID FROM B);

SELECT COUNT(*)
  FROM A LEFT OUTER JOIN B ON (A.ID = B.ID)
         LEFT OUTER JOIN C ON (B.ID = C.ID);

UPDATE EMP
   SET SAL = SAL * 1.1
 WHERE SAL >= 3000;

UPDATE EMP
   SET SAL = SAL * 1.1
 WHERE NAME IN (SELECT NAME FROM EMP WHERE SAL IS NOT NULL);

INSERT INTO T1 VALUES (1);
INSERT INTO T1 VALUES (2);
SAVEPOINT S1;
UPDATE T1 SET C1 = 4 WHERE C1 = 1;
DELETE FROM T1 WHERE C1 = 2;
ROLLBACK TO S1;
INSERT INTO T1 VALUES (3);
SELECT AVG(C1) FROM T1;

CREATE TABLE T (
    A CHAR(2),
    B CHAR(3),
    C VARCHAR2(2),
    D VARCHAR2(3)
);
INSERT INTO T VALUES ('1', '1', '1', '1');
